import redis
import logging
import json
import os
from datetime import datetime
from functools import wraps
import time

# Redis configuration
REDIS_URL = os.environ.get('REDIS_URL', 'redis://localhost:6379/0')
CACHE_VERSION = "1.1"
MAX_RETRIES = 3
BASE_BACKOFF = 0.1
DRAWING_CACHE_TIMEOUT = 3600  # 1 hour
ROOM_CACHE_TIMEOUT = 86400   # 24 hours
USER_PRESENCE_TIMEOUT = 300  # 5 minutes
PREFETCH_THRESHOLD = 10      # Number of accesses before prefetching

# Initialize Redis connection pool with optimized settings
redis_pool = redis.ConnectionPool.from_url(
    REDIS_URL,
    max_connections=20,
    socket_timeout=2,
    socket_connect_timeout=2,
    retry_on_timeout=True,
    decode_responses=True,
    health_check_interval=30
)

redis_client = redis.Redis(connection_pool=redis_pool, decode_responses=True)

def get_cache_key(base_key, version=CACHE_VERSION):
    """Generate versioned cache key"""
    return f"{base_key}:v{version}"

def retry_with_backoff(func):
    """Enhanced retry decorator with exponential backoff and Redis-specific error handling"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        for attempt in range(MAX_RETRIES):
            try:
                return func(*args, **kwargs)
            except redis.ConnectionError as e:
                if attempt == MAX_RETRIES - 1:
                    logging.error(f"Redis connection failed after {MAX_RETRIES} attempts: {str(e)}")
                    raise
                backoff = BASE_BACKOFF * (2 ** attempt)
                logging.warning(f"Redis connection failed (attempt {attempt + 1}): {str(e)}. Retrying in {backoff}s")
                time.sleep(backoff)
            except redis.RedisError as e:
                logging.error(f"Redis operation error: {str(e)}")
                raise
            except Exception as e:
                logging.error(f"Unexpected cache error: {str(e)}")
                raise
    return wrapper

def log_cache_stats(func):
    """Log cache hit/miss statistics"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        duration = time.time() - start_time

        # Log cache operation stats
        cache_status = "hit" if result is not None else "miss"
        logging.info(f"Cache {cache_status} - Key: {kwargs.get('cache_key')} - Duration: {duration:.3f}s")

        return result
    return wrapper


def cache_drawing(timeout=300):
    """Enhanced caching decorator with retry and monitoring"""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            room_id = kwargs.get('room_id')
            base_key = f"drawing_{room_id}"
            cache_key = get_cache_key(base_key)
            kwargs['cache_key'] = cache_key  # For logging

            @retry_with_backoff
            @log_cache_stats
            def get_cached_data():
                return redis_client.get(cache_key)

            @retry_with_backoff
            def set_cached_data(data):
                redis_client.set(cache_key, data, timeout=timeout)
                # Update access patterns for prefetching
                update_access_pattern(room_id)

            # Try to get cached data
            cached_data = get_cached_data()
            if cached_data is not None:
                return cached_data

            # Get fresh data
            data = f(*args, **kwargs)
            if data is not None:
                set_cached_data(data)
            return data

        return decorated_function
    return decorator

def update_access_pattern(room_id):
    """Track room access patterns for prefetching"""
    pattern_key = f"access_pattern:{room_id}"
    try:
        redis_client.set(
            pattern_key,
            {
                'last_access': datetime.utcnow().isoformat(),
                'access_count': redis_client.get(pattern_key, {}).get('access_count', 0) + 1
            },
            timeout=86400  # 24 hours
        )
    except Exception as e:
        logging.warning(f"Failed to update access pattern: {str(e)}")

def prefetch_room_data(room_id):
    """Prefetch room data based on access patterns"""
    pattern_key = f"access_pattern:{room_id}"
    try:
        pattern = redis_client.get(pattern_key)
        if pattern and pattern.get('access_count', 0) > PREFETCH_THRESHOLD:
            # Room is frequently accessed, prefetch related data
            logging.info(f"Prefetching data for frequently accessed room: {room_id}")

            # Prefetch drawing data
            from models import DrawingData # Assumed this import is available
            drawings = DrawingData.query.filter_by(room_id=room_id).all()
            if drawings:
                try:
                    drawing_data = [json.loads(d.data) for d in drawings]
                    cache_key = get_cache_key(f"drawing_data_{room_id}")

                    @retry_with_backoff
                    def cache_drawings():
                        redis_client.setex(
                            cache_key,
                            DRAWING_CACHE_TIMEOUT,
                            json.dumps(drawing_data, separators=(',', ':'))
                        )

                    cache_drawings()
                    logging.info(f"Successfully prefetched {len(drawing_data)} drawings for room {room_id}")
                except json.JSONDecodeError as e:
                    logging.error(f"Error parsing drawing data during prefetch: {e}")
    except Exception as e:
        logging.warning(f"Failed to prefetch room data: {str(e)}")

@retry_with_backoff
def cache_room_state(room_id, state_data, timeout=ROOM_CACHE_TIMEOUT):
    """Cache room state including viewport and active users"""
    try:
        cache_key = get_cache_key(f"room_state_{room_id}")
        redis_client.setex(
            cache_key,
            timeout,
            json.dumps(state_data, separators=(',', ':'))
        )
        logging.info(f"Cached room state for room {room_id}")
    except Exception as e:
        logging.error(f"Failed to cache room state: {str(e)}")

@retry_with_backoff
def get_room_state(room_id):
    """Retrieve cached room state"""
    try:
        cache_key = get_cache_key(f"room_state_{room_id}")
        data = redis_client.get(cache_key)
        if data:
            return json.loads(data)
    except Exception as e:
        logging.error(f"Failed to get room state: {str(e)}")
    return None

@retry_with_backoff
def track_user_presence(room_id, user_id, user_data):
    """Track user presence in a room with cursor position caching"""
    try:
        presence_key = get_cache_key(f"presence_{room_id}")
        user_key = str(user_id)  # Ensure key is string

        # Add timestamp to user data for cleanup
        user_data['last_seen'] = datetime.utcnow().isoformat()

        # Serialize user data
        serialized_data = json.dumps(user_data)

        # Update user data in room with pipeline for atomicity
        pipe = redis_client.pipeline()
        pipe.hset(presence_key, user_key, serialized_data)
        pipe.expire(presence_key, USER_PRESENCE_TIMEOUT)
        pipe.execute()

        logging.info(f"Updated presence for user {user_id} in room {room_id}")

        # Cleanup disconnected users periodically
        cleanup_disconnected_users(room_id)
    except Exception as e:
        logging.error(f"Failed to track user presence: {str(e)}")

@retry_with_backoff
def get_active_users(room_id):
    """Get all active users in a room"""
    try:
        presence_key = get_cache_key(f"presence_{room_id}")
        user_data = redis_client.hgetall(presence_key)
        # Decode bytes to string if needed and parse JSON
        return {
            k.decode('utf-8') if isinstance(k, bytes) else k: 
            json.loads(v.decode('utf-8') if isinstance(v, bytes) else v)
            for k, v in user_data.items()
        }
    except Exception as e:
        logging.error(f"Failed to get active users: {str(e)}")
        return {}

@retry_with_backoff
def invalidate_room_cache(room_id):
    """Invalidate all cached data for a room"""
    try:
        # Get all keys for the room
        room_pattern = get_cache_key(f"*_{room_id}")
        keys = redis_client.keys(room_pattern)

        if keys:
            redis_client.delete(*keys)
            logging.info(f"Invalidated cache for room {room_id}")
    except Exception as e:
        logging.error(f"Failed to invalidate room cache: {str(e)}")
@retry_with_backoff
def cleanup_disconnected_users(room_id):
    """Remove users who haven't updated their presence recently"""
    try:
        presence_key = get_cache_key(f"presence_{room_id}")
        now = datetime.utcnow()
        users = get_active_users(room_id)

        pipe = redis_client.pipeline()
        for user_id, data in users.items():
            last_seen = datetime.fromisoformat(data.get('last_seen', '2000-01-01'))
            if (now - last_seen).total_seconds() > USER_PRESENCE_TIMEOUT:
                pipe.hdel(presence_key, str(user_id))
        pipe.execute()
    except Exception as e:
        logging.error(f"Failed to cleanup disconnected users: {str(e)}")

@retry_with_backoff
def cache_cursor_position(room_id, user_id, position_data, timeout=2):
    """Cache cursor position with optimized connection handling"""
    if not check_redis_connection():
        logging.error("Redis connection is not available")
        return

    try:
        cursor_key = get_cache_key(f"cursor_{room_id}_{user_id}")
        with redis_client.pipeline(transaction=False) as pipe:
            try:
                # Set cursor position with expiration
                pipe.setex(cursor_key, timeout, json.dumps(position_data))
                pipe.execute()
                logging.debug(f"Successfully cached cursor position for user {user_id} in room {room_id}")
            except redis.RedisError as e:
                logging.error(f"Redis operation failed: {str(e)}")
            except Exception as e:
                logging.error(f"Unexpected error in cursor caching: {str(e)}")
    except Exception as e:
        logging.error(f"Failed to cache cursor position: {str(e)}")
    finally:
        try:
            # Safely release connection
            if hasattr(redis_client, 'connection') and redis_client.connection:
                redis_client.connection_pool.release(redis_client.connection)
        except Exception as e:
            logging.error(f"Error releasing Redis connection: {str(e)}")

@retry_with_backoff
def get_cursor_positions(room_id):
    """Get all active cursor positions in a room"""
    try:
        pattern = get_cache_key(f"cursor_{room_id}_*")
        cursor_keys = redis_client.keys(pattern)
        positions = {}

        for key in cursor_keys:
            user_id = key.split('_')[-1]
            data = redis_client.get(key)
            if data:
                positions[user_id] = json.loads(data)
        return positions
    except Exception as e:
        logging.error(f"Failed to get cursor positions: {str(e)}")
        return {}

def check_redis_connection():
    """Enhanced Redis connection health check with retry"""
    for attempt in range(3):
        try:
            if redis_client.ping():
                if attempt > 0:
                    logging.info("Redis connection restored")
                return True
        except redis.ConnectionError as e:
            if attempt == 2:
                logging.error(f"Redis connection failed after 3 attempts: {e}")
            else:
                logging.warning(f"Redis connection attempt {attempt + 1} failed: {e}")
                time.sleep(0.1 * (2 ** attempt))  # Exponential backoff
        except Exception as e:
            logging.error(f"Unexpected Redis error: {e}")
            break
    return False

# Export the redis client as cache
cache = redis_client

import os
from datetime import datetime
from flask import Flask, render_template, request, jsonify
from flask_socketio import emit, join_room
import json
import logging

from extensions import db, socketio
from cache_manager import (
    cache, check_redis_connection, cache_room_state,
    track_user_presence, get_active_users, prefetch_room_data,
    cache_cursor_position  # Add cursor position caching
)

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(24)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///whiteboard.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

# Initialize extensions
db.init_app(app)
socketio.init_app(app)

# Import models after db initialization
import models

@app.route('/health')
def health_check():
    """Health check endpoint for k8s and monitoring"""
    redis_status = check_redis_connection()
    return jsonify({
        'status': 'healthy' if redis_status else 'degraded',
        'redis': 'connected' if redis_status else 'disconnected',
        'timestamp': datetime.utcnow().isoformat()
    }), 200 if redis_status else 503

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/room/<room_id>')
def room(room_id):
    # Create room if it doesn't exist
    room = models.Room.query.get(room_id)
    if not room:
        room = models.Room(id=room_id)
        db.session.add(room)
        db.session.commit()
    return render_template('room.html', room_id=room_id)

@app.route('/room/<room_id>/drawings')
def get_room_drawings(room_id):
    try:
        logger.info(f"Fetching drawings for room {room_id}")

        # Try to get from cache first
        cache_key = f"drawing_data_{room_id}"
        cached_data = cache.get(cache_key)

        if cached_data:
            logger.info("Retrieved drawings from cache")
            return {"drawings": json.loads(cached_data)}

        # If not in cache, get from database
        drawings = models.DrawingData.query.filter_by(room_id=room_id).all()
        drawing_data = []

        for drawing in drawings:
            try:
                path_obj = json.loads(drawing.data)
                drawing_data.append(path_obj)
            except json.JSONDecodeError as e:
                logger.error(f"Error parsing drawing data: {e}")
                continue

        # Update cache with fresh data
        cache.setex(cache_key, 3600, json.dumps(drawing_data))
        logger.info(f"Found {len(drawing_data)} drawings for room {room_id}")
        return {"drawings": drawing_data}

    except Exception as e:
        logger.error(f"Error retrieving drawings: {e}")
        return {"drawings": [], "error": str(e)}

# Room user count tracking
room_users = {}

@socketio.on('connect')
def handle_connect():
    logger.info(f"Client connected: {request.sid}")

@socketio.on('join')
def handle_join(data):
    room = data['room']
    join_room(room)

    try:
        # Update user count with proper room tracking
        if room not in room_users:
            room_users[room] = set()
        room_users[room].add(request.sid)
        user_count = len(room_users[room])

        # Track user presence in Redis
        user_data = {
            'sid': request.sid,
            'joined_at': datetime.utcnow().isoformat(),
            'user_name': data.get('userName', 'Anonymous')
        }
        track_user_presence(room, request.sid, user_data)

        # Cache room state
        cache_room_state(room, {
            'user_count': user_count,
            'last_update': datetime.utcnow().isoformat()
        })

        # Prefetch room data for frequently accessed rooms
        prefetch_room_data(room)

        # Broadcast user count to all clients in room
        socketio.emit('user_joined', {
            'count': user_count,
            'users': get_active_users(room)
        }, room=room)

        logger.info(f"Client {request.sid} joined room {room}, total users: {user_count}")

    except Exception as e:
        logger.error(f"Error in handle_join: {str(e)}")
        # Ensure basic functionality even if caching fails
        socketio.emit('user_joined', {'count': len(room_users.get(room, set()))}, room=room)

@socketio.on('draw')
def handle_draw(data):
    room = data['room']
    try:
        logger.info(f"Received draw event for room {room}")

        # Store in database with proper serialization
        path_data = json.dumps(data['path'], separators=(',', ':'))
        drawing = models.DrawingData(room_id=room, data=path_data)
        db.session.add(drawing)
        db.session.commit()

        # Update cache atomically
        cache_key = f"drawing_data_{room}"
        try:
            cached_data = cache.get(cache_key)
            drawing_list = json.loads(cached_data) if cached_data else []
            drawing_list.append(data['path'])
            cache.setex(cache_key, 3600, json.dumps(drawing_list, separators=(',', ':')))
            logger.info(f"Successfully updated cache for room {room}")
        except Exception as e:
            logger.error(f"Cache update failed: {e}")

        # Broadcast to room
        emit('draw_update', {
            'room': room,
            'path': data['path']
        }, room=room, include_self=False)

    except Exception as e:
        logger.error(f"Error handling draw event: {e}")
        db.session.rollback()

@socketio.on('disconnect')
def handle_disconnect():
    # Update user count for all rooms user was in
    for room in list(room_users.keys()):  # Use list to avoid runtime modification
        if request.sid in room_users[room]:
            room_users[room].remove(request.sid)
            user_count = len(room_users[room])
            socketio.emit('user_left', {'count': user_count}, room=room)
            logger.info(f"Client {request.sid} left room {room}, remaining users: {user_count}")

            # Clean up empty rooms
            if len(room_users[room]) == 0:
                del room_users[room]

    logger.info(f"Client disconnected: {request.sid}")

@socketio.on('undo')
def handle_undo(data):
    room = data['room']
    socketio.emit('undo_update', {
        'room': room,
        'objectData': data.get('objectData')
    }, room=room, skip_sid=request.sid)

@socketio.on('redo')
def handle_redo(data):
    room = data['room']
    socketio.emit('redo_update', {
        'room': room,
        'objectData': data.get('objectData')
    }, room=room, skip_sid=request.sid)

@socketio.on('cursor_move')
def handle_cursor_move(data):
    room = data['room']
    try:
        # Cache cursor position
        cursor_data = {
            'userName': data['userName'],
            'x': data['x'],
            'y': data['y'],
            'timestamp': datetime.utcnow().isoformat()
        }
        cache_cursor_position(room, request.sid, cursor_data)

        # Broadcast to room
        emit('cursor_update', {
            'room': room,
            'userName': data['userName'],
            'x': data['x'],
            'y': data['y']
        }, room=room, include_self=False)
    except Exception as e:
        logger.error(f"Error handling cursor move: {str(e)}")


@socketio.on('viewport_update')
def handle_viewport_update(data):
    """Handle viewport updates and cache room state"""
    room = data['room']
    try:
        from cache_manager import cache_room_state
        cache_room_state(room, {
            'viewport': data['viewport'],
            'last_update': datetime.utcnow().isoformat()
        })
        emit('viewport_update', data, room=room, skip_sid=request.sid)
    except Exception as e:
        logger.error(f"Error caching viewport state: {e}")

@socketio.on('clear')
def handle_clear(data):
    room = data['room']
    try:
        # Clear cached drawing data
        cache_key = f"drawing_data_{room}"
        cache.delete(cache_key)

        # Clear drawings from database
        models.DrawingData.query.filter_by(room_id=room).delete()
        db.session.commit()

        socketio.emit('clear_board', room=room, skip_sid=request.sid)
    except Exception as e:
        logger.error(f"Error clearing drawings: {str(e)}")
        db.session.rollback()
        socketio.emit('error', {'message': 'Failed to clear drawings'}, room=request.sid)

if __name__ == '__main__':
    socketio.run(app, host='0.0.0.0', port=5000, debug=True)

from app import app, socketio

if __name__ == "__main__":
    socketio.run(app, host="0.0.0.0", port=5001, debug=True)

class SocketManager {
    constructor() {
        this.socket = io();
        this.lastRoom = null;
        this.userName = '';
        this.cursors = new Map();
        this.setupEventListeners();
    }

    setupEventListeners() {
        this.socket.on('connect', () => {
            console.log('Connected to server');
            // Re-join room if reconnecting
            if (this.lastRoom) {
                this.socket.emit('join', { room: this.lastRoom });
            }
        });

        this.socket.on('disconnect', () => {
            console.log('Disconnected from server');
        });

        this.socket.on('connect_error', (error) => {
            console.error('Connection error:', error);
        });

        this.socket.on('user_joined', (data) => {
            const userCount = document.getElementById('activeUsers');
            if (userCount) {
                userCount.textContent = `Users: ${data.count}`;
            }
        });

        this.socket.on('user_left', (data) => {
            const userCount = document.getElementById('activeUsers');
            if (userCount) {
                userCount.textContent = `Users: ${data.count}`;
            }
        });
    }

    setUserName(name) {
        this.userName = name;
    }

    joinRoom(roomId) {
        console.log('Joining room:', roomId);
        this.lastRoom = roomId;
        this.socket.emit('join', { 
            room: roomId,
            userName: this.userName
        });
    }

    emit(event, data) {
        try {
            // Always include userName in events
            const dataWithUser = {
                ...data,
                userName: this.userName || 'Anonymous'  // Ensure userName is never undefined
            };
            console.log('Emitting event with data:', dataWithUser);  // Debug log
            this.socket.emit(event, dataWithUser);
        } catch (error) {
            console.error('Error emitting event:', error);
        }
    }

    on(event, callback) {
        this.socket.on(event, (data) => {
            try {
                callback(data);
            } catch (error) {
                console.error(`Error handling ${event} event:`, error);
            }
        });
    }

    disconnect() {
        if (this.socket) {
            this.socket.disconnect();
        }
    }
}

class Whiteboard {
    constructor(canvasId, socket, roomId) {
        this.canvas = new fabric.Canvas(canvasId, {
            isDrawingMode: true,
            width: window.innerWidth * 0.9,
            height: window.innerHeight * 0.8,
            backgroundColor: '#ffffff',
            selection: false
        });
        this.socket = socket;
        this.roomId = roomId;
        this.history = [];
        this.redoStack = [];
        this.currentMode = 'draw';
        this.isDrawing = false;
        this.cursors = new Map();

        // Add object management
        this.canvas.preserveObjectStacking = true;
        this.canvas.renderOnAddRemove = false;

        // Batch rendering
        this.pendingRender = false;
        this.batchRender = () => {
            if (!this.pendingRender) {
                this.pendingRender = true;
                requestAnimationFrame(() => {
                    this.canvas.renderAll();
                    this.pendingRender = false;
                });
            }
        };

        // Initialize viewport state
        this.viewportState = {
            zoom: 1,
            pan: { x: 0, y: 0 }
        };

        this.initResponsiveCanvas();
        this.setupTools();
        this.setupEventListeners();
        this.loadExistingDrawings();

        // Join room immediately after socket setup
        this.socket.joinRoom(this.roomId);
    }

    setupTools() {
        // Initialize brush settings
        this.canvas.freeDrawingBrush.width = 2;
        this.canvas.freeDrawingBrush.color = '#000000';

        // Initialize drawing modes
        this.modes = {
            draw: this.initDrawMode.bind(this),
            rect: this.initRectMode.bind(this),
            circle: this.initCircleMode.bind(this)
        };
        this.setMode('draw');
    }

    setMode(mode) {
        if (!this.modes[mode]) return;
        this.currentMode = mode;
        this.modes[mode]();
        // Update UI to show active mode
        document.querySelectorAll('.tool-group button').forEach(btn => {
            btn.classList.remove('active');
        });
        document.querySelector(`button[onclick="whiteboard.setMode('${mode}')"]`).classList.add('active');
    }

    updateCursor(data) {
        console.log('Updating cursor for:', data.userName);

        // Remove existing cursor
        const existingCursor = this.canvas.getObjects().find(
            obj => obj.type === 'group' && obj.id === `cursor_${data.userName}`
        );
        if (existingCursor) {
            this.canvas.remove(existingCursor);
        }

        // Create cursor triangle
        const cursor = new fabric.Triangle({
            width: 20,
            height: 20,
            fill: '#ff4444',
            stroke: '#000000',
            strokeWidth: 1,
            angle: 45,
            originX: 'center',
            originY: 'center',
            selectable: false,
            evented: false
        });

        // Create background for text with increased width
        const textBg = new fabric.Rect({
            fill: 'rgba(0, 0, 0, 0.8)',
            width: 120,
            height: 30,
            rx: 15,
            ry: 15,
            originX: 'center',
            originY: 'center',
            selectable: false,
            evented: false
        });

        // Create username text with adjusted position
        const text = new fabric.Text(data.userName || 'Anonymous', {
            fontSize: 16,
            fill: '#ffffff',
            fontFamily: 'Arial',
            fontWeight: 'bold',
            originX: 'center',
            originY: 'center',
            selectable: false,
            evented: false
        });

        // Position text and background above cursor
        const textGroup = new fabric.Group([textBg, text], {
            left: 0,
            top: -40,
            selectable: false,
            evented: false
        });

        // Adjust background width to text
        textBg.set({
            width: Math.max(text.width + 20, 80)
        });

        // Create main cursor group with high z-index
        const cursorGroup = new fabric.Group([cursor, textGroup], {
            left: data.x,
            top: data.y,
            selectable: false,
            evented: false,
            id: `cursor_${data.userName}`,
            zIndex: 999
        });

        // Add to canvas and ensure it's on top
        this.canvas.add(cursorGroup);
        cursorGroup.bringToFront();

        // Force canvas refresh
        this.canvas.requestRenderAll();
    }

    setupEventListeners() {
        // Add cursor tracking with throttling
        let lastEmit = 0;
        const EMIT_INTERVAL = 50; // 50ms throttle

        this.canvas.on('mouse:move', (opt) => {
            const now = Date.now();
            if (now - lastEmit > EMIT_INTERVAL) {
                const pointer = this.canvas.getPointer(opt.e);

                // Ensure pointer coordinates are within canvas bounds
                const x = Math.min(Math.max(pointer.x, 0), this.canvas.width);
                const y = Math.min(Math.max(pointer.y, 0), this.canvas.height);

                this.socket.emit('cursor_move', {
                    room: this.roomId,
                    x: x,
                    y: y
                });
                lastEmit = now;
            }
        });

        // Handle other users' cursors
        this.socket.on('cursor_update', (data) => {
            console.log('Received cursor update:', data);  // Debug log
            if (data.room === this.roomId && data.userName !== this.socket.userName) {
                this.updateCursor(data);
            }
        });

        // Add viewport state tracking
        this.canvas.on('zoom:changed', () => {
            this.viewportState.zoom = this.canvas.getZoom();
            this.socket.emit('viewport_update', {
                room: this.roomId,
                viewport: this.viewportState
            });
        });

        // Handle viewport updates from other users
        this.socket.on('viewport_update', (data) => {
            if (data.room === this.roomId) {
                this.viewportState = data.viewport;
                this.canvas.setZoom(data.viewport.zoom);
                this.canvas.absolutePan(new fabric.Point(
                    data.viewport.pan.x,
                    data.viewport.pan.y
                ));
            }
        });

        // Handle drawing updates
        this.canvas.on('path:created', (e) => {
            const path = e.path;
            this.history.push(path);
            this.socket.emit('draw', {
                room: this.roomId,
                path: path.toJSON()
            });
        });

        this.socket.on('draw_update', async (data) => {
            if (data.room === this.roomId) {
                try {
                    const path = data.path;
                    await new Promise(resolve => {
                        fabric.util.enlivenObjects([path], (objects) => {
                            objects.forEach(obj => {
                                this.canvas.add(obj);
                                this.history.push(obj);
                            });
                            this.canvas.renderAll();
                            resolve();
                        });
                    });
                } catch (error) {
                    console.error('Error handling draw update:', error);
                }
            }
        });

        // Handle undo/redo
        this.socket.on('undo_update', (data) => {
            if (data.room === this.roomId && this.history.length > 0) {
                const removed = this.history.pop();
                this.redoStack.push(removed);
                this.canvas.remove(removed);
                this.canvas.renderAll();
            }
        });

        this.socket.on('redo_update', (data) => {
            if (data.room === this.roomId && this.redoStack.length > 0) {
                const restored = this.redoStack.pop();
                this.history.push(restored);
                this.canvas.add(restored);
                this.canvas.renderAll();
            }
        });

        // Handle clear board
        this.socket.on('clear_board', () => {
            this.canvas.clear();
        });
    }

    initDrawMode() {
        this.canvas.isDrawingMode = true;
        this.canvas.off('mouse:down');
        this.canvas.off('mouse:move');
        this.canvas.off('mouse:up');
    }

    initRectMode() {
        this.canvas.isDrawingMode = false;
        let rect, origX, origY;

        this.canvas.on('mouse:down', (o) => {
            this.isDrawing = true;
            const pointer = this.canvas.getPointer(o.e);
            origX = pointer.x;
            origY = pointer.y;

            rect = new fabric.Rect({
                left: origX,
                top: origY,
                width: 0,
                height: 0,
                fill: 'transparent',
                stroke: this.canvas.freeDrawingBrush.color,
                strokeWidth: this.canvas.freeDrawingBrush.width,
                selectable: false
            });
            this.canvas.add(rect);
        });

        this.canvas.on('mouse:move', (o) => {
            if (!this.isDrawing) return;
            const pointer = this.canvas.getPointer(o.e);

            const width = Math.abs(pointer.x - origX);
            const height = Math.abs(pointer.y - origY);

            rect.set({
                width: width,
                height: height,
                left: Math.min(origX, pointer.x),
                top: Math.min(origY, pointer.y)
            });
            this.canvas.renderAll();
        });

        this.canvas.on('mouse:up', () => {
            this.isDrawing = false;
            this.history.push(rect);
            this.redoStack = [];
            this.socket.emit('draw', {
                room: this.roomId,
                path: rect.toJSON()
            });
        });
    }

    initCircleMode() {
        this.canvas.isDrawingMode = false;
        let circle, origX, origY;

        this.canvas.on('mouse:down', (o) => {
            this.isDrawing = true;
            const pointer = this.canvas.getPointer(o.e);
            origX = pointer.x;
            origY = pointer.y;

            circle = new fabric.Circle({
                left: origX,
                top: origY,
                radius: 0,
                fill: 'transparent',
                stroke: this.canvas.freeDrawingBrush.color,
                strokeWidth: this.canvas.freeDrawingBrush.width,
                selectable: false
            });
            this.canvas.add(circle);
        });

        this.canvas.on('mouse:move', (o) => {
            if (!this.isDrawing) return;
            const pointer = this.canvas.getPointer(o.e);
            const radius = Math.sqrt(
                Math.pow(pointer.x - origX, 2) +
                Math.pow(pointer.y - origY, 2)
            ) / 2;

            circle.set({
                radius: radius
            });
            this.canvas.renderAll();
        });

        this.canvas.on('mouse:up', () => {
            this.isDrawing = false;
            this.history.push(circle);
            this.redoStack = [];
            this.socket.emit('draw', {
                room: this.roomId,
                path: circle.toJSON()
            });
        });
    }

    async loadExistingDrawings() {
        try {
            const response = await fetch(`/room/${this.roomId}/drawings`);
            if (!response.ok) throw new Error('Failed to fetch drawings');

            const data = await response.json();
            if (data.drawings && Array.isArray(data.drawings)) {
                for (const path of data.drawings) {
                    if (path && typeof path === 'object') {
                        await new Promise(resolve => {
                            fabric.util.enlivenObjects([path], (objects) => {
                                objects.forEach(obj => {
                                    this.canvas.add(obj);
                                    this.history.push(obj);
                                });
                                this.canvas.renderAll();
                                resolve();
                            });
                        });
                    }
                }
            }
        } catch (error) {
            console.error('Error loading existing drawings:', error);
        }
    }

    initResponsiveCanvas() {
        this.resizeCanvas();
        window.addEventListener('resize', () => {
            this.resizeCanvas();
        });
    }

    resizeCanvas() {
        const container = document.querySelector('.whiteboard-container');
        const containerWidth = container.clientWidth;
        const containerHeight = window.innerHeight * 0.8;

        let newWidth = containerWidth - 40;
        let newHeight = containerHeight;

        this.canvas.setWidth(newWidth);
        this.canvas.setHeight(newHeight);
        this.canvas.renderAll();
    }

    setColor(color) {
        this.canvas.freeDrawingBrush.color = color;
    }

    setBrushSize(size) {
        this.canvas.freeDrawingBrush.width = size;
    }

    clear() {
        this.canvas.clear();
        this.socket.emit('clear', { room: this.roomId });
    }

    undo() {
        if (this.history.length > 0) {
            const removed = this.history.pop();
            this.redoStack.push(removed);
            this.canvas.remove(removed);
            this.canvas.renderAll();
            this.socket.emit('undo', { 
                room: this.roomId,
                objectData: removed.toJSON()
            });
        }
    }

    redo() {
        if (this.redoStack.length > 0) {
            const restored = this.redoStack.pop();
            this.history.push(restored);
            this.canvas.add(restored);
            this.canvas.renderAll();
            this.socket.emit('redo', { 
                room: this.roomId,
                objectData: restored.toJSON()
            });
        }
    }
}
